import{_ as t,o,c as r,a3 as a}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Product Roadmap","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Product Roadmap | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/getting-started/product-roadmap"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Product Roadmap | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/getting-started/product-roadmap"}]]},"headers":[],"relativePath":"getting-started/product-roadmap.md","filePath":"getting-started/product-roadmap.md","lastUpdated":1791470118000}'),d={name:"getting-started/product-roadmap.md"};function s(n,e,i,c,p,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="product-roadmap" tabindex="-1">Product Roadmap <a class="header-anchor" href="#product-roadmap" aria-label="Permalink to &quot;Product Roadmap&quot;">​</a></h1><p>Canonical delivery status for EloSync modules and platform capabilities. Keep this page aligned with <a href="/architecture/module-dependencies">module dependencies</a>, <a href="/changelog/">changelog</a>, user-guide overviews, and the marketing site roadmap.</p><p><strong>Legend:</strong> Shipped = available in product; Deferred = documented later work; Demand-driven = only when beta tenants ask.</p><hr><h2 id="phase-1-—-crm-foundation-shipped" tabindex="-1">Phase 1 — CRM Foundation (shipped) <a class="header-anchor" href="#phase-1-—-crm-foundation-shipped" aria-label="Permalink to &quot;Phase 1 — CRM Foundation (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/leads-overview">Leads</a>, <a href="/user-guide/tasks-overview">Tasks</a>, <a href="/user-guide/todos-overview">ToDos</a></td><td>Shipped (default-included; Leads <strong>1.9.0</strong> inactivity manager digest; <strong>1.8.0</strong> real-time board sync; <strong>1.7.0</strong> convert opportunity gates; Tasks <strong>1.8.0</strong> real-time board sync; <strong>1.5.0</strong> milestone link + dependencies)</td></tr><tr><td><a href="/user-guide/contacts-overview">Contacts</a>, <a href="/user-guide/companies-overview">Companies</a></td><td>Shipped (Contacts <strong>1.7.0</strong> / Companies <strong>1.4.0</strong> follow-ups + import/export)</td></tr><tr><td><a href="/user-guide/calendar-overview">Calendar</a>, <a href="/user-guide/meetings-overview">Meetings</a></td><td>Shipped (Meetings requires Calendar; Calendar <strong>1.9.0</strong> named team/department calendars; <strong>1.8.0</strong> webhook-driven near real-time inbound; <strong>1.7.0</strong> Project/Contact/Company overlay push; <strong>1.6.0</strong> two-way sync + External pull; <strong>1.5.0</strong> Meeting/Task/Lead overlay push; <strong>1.4.0</strong> OAuth push)</td></tr><tr><td><a href="/user-guide/activities-overview">Activities</a>, <a href="/user-guide/communication-templates">Communication Templates</a></td><td>Shipped</td></tr><tr><td>Module Marketplace</td><td>Shipped</td></tr><tr><td>Meta Lead Ads / inbound webhooks</td><td>Shipped</td></tr><tr><td><a href="/user-guide/whatsapp-cloud-overview">WhatsApp Cloud</a></td><td>Shipped (billable; media + Automation triggers + interactive buttons/lists <strong>1.4.0</strong>)</td></tr></tbody></table><h3 id="planned-deferred-after-phase-1-mvp" tabindex="-1">Planned / deferred after Phase 1 MVP <a class="header-anchor" href="#planned-deferred-after-phase-1-mvp" aria-label="Permalink to &quot;Planned / deferred after Phase 1 MVP&quot;">​</a></h3><ul><li>Calendar: named-calendar provider sync/watches; per-provider <code>external_event_id</code> mapping is still single-value (named team calendars, P/C/C overlay push, and webhook-driven inbound shipped <strong>1.7.0–1.9.0</strong>)</li><li>WhatsApp: alternate BSPs, AI WhatsApp features</li></ul><p><strong>Shipped depth (CRM):</strong> Calendar Task/Lead overlays (<strong>calendar 1.1.0</strong>); meeting invitee Calendar ACL (<strong>calendar 1.2.0</strong>); Lead convert polish (<strong>leads 1.5.0</strong>); Lead <strong>created_by / updated_by</strong> filters and columns (<strong>leads 1.6.0</strong>); Lead convert opportunity settings (<strong>leads 1.7.0</strong>); Lead real-time board sync (<strong>leads 1.8.0</strong>); Lead inactivity manager digest (<strong>leads 1.9.0</strong>); Tasks real-time board sync (<strong>tasks 1.8.0</strong>); Calendar Google/Outlook sync Phase 1 — per-user OAuth connect, one-way push for manual events (<strong>calendar 1.4.0</strong>); Meeting/Task/Lead overlay provider push (<strong>calendar 1.5.0</strong>); Project/Contact/Company overlay provider push (<strong>calendar 1.7.0</strong>); webhook-driven near real-time inbound sync (<strong>calendar 1.8.0</strong>); named team/department calendars (<strong>calendar 1.9.0</strong>).</p><hr><h2 id="phase-2-—-sales-expansion-shipped" tabindex="-1">Phase 2 — Sales Expansion (shipped) <a class="header-anchor" href="#phase-2-—-sales-expansion-shipped" aria-label="Permalink to &quot;Phase 2 — Sales Expansion (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/opportunities-overview">Opportunities</a> (pipeline + Kanban)</td><td>Shipped (<strong>1.3.0</strong> real-time board sync)</td></tr><tr><td><a href="/user-guide/quotations-overview">Quotations</a></td><td>Shipped (requires Opportunities; customer e-signature accept links <strong>1.9.0</strong>)</td></tr><tr><td><a href="/user-guide/contracts-overview">Contracts</a></td><td>Shipped (requires Opportunities; PDF + e-signature <strong>1.5.0</strong>; renewal reminders <strong>1.6.0</strong>; accept evidence toggles <strong>1.7.0</strong>; auto-renew <strong>1.8.0</strong>)</td></tr><tr><td><a href="/user-guide/resellers-overview">Resellers</a> / <a href="/user-guide/reseller-payouts-overview">Reseller Payouts</a></td><td>Shipped (free Sales opt-ins; Payments → Resellers → Payouts chain)</td></tr></tbody></table><h3 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Quotation multi-signer / third-party e-sign providers; multi-currency; approval workflows beyond status enums</li><li>Contract multi-signer / third-party e-sign providers</li><li>Reseller cross-workspace identity; reseller portal; automated bank disbursement</li></ul><hr><h2 id="phase-3-—-billing-shipped" tabindex="-1">Phase 3 — Billing (shipped) <a class="header-anchor" href="#phase-3-—-billing-shipped" aria-label="Permalink to &quot;Phase 3 — Billing (shipped)&quot;">​</a></h2><p>Tenant customer billing — not a redesign of Central Marketplace billing.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/invoices-overview">Invoices</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/estimates-overview">Estimates</a></td><td>Shipped (requires Invoices)</td></tr><tr><td><a href="/user-guide/credit-notes-overview">Credit Notes</a></td><td>Shipped <strong>1.2.0</strong> (requires Invoices; PDF + email; applied refund)</td></tr><tr><td><a href="/user-guide/payments-overview">Payments</a></td><td>Shipped (requires Invoices; receipt PDF + email shipped)</td></tr></tbody></table><h3 id="deferred-1" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-1" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Credit Notes: standalone notes not tied to an invoice; multi-currency</li><li>Payments: partial refunds; payment-gateway capture</li><li>Invoices / Estimates: multi-currency conversion</li></ul><hr><h2 id="phase-4-—-purchasing-shipped" tabindex="-1">Phase 4 — Purchasing (shipped) <a class="header-anchor" href="#phase-4-—-purchasing-shipped" aria-label="Permalink to &quot;Phase 4 — Purchasing (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/vendors-overview">Vendors</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/purchase-orders-overview">Purchase Orders</a></td><td>Shipped (requires Vendors; PDF + email; per-line partial receive <strong>1.5.0</strong>)</td></tr><tr><td><a href="/user-guide/expenses-overview">Expenses</a></td><td>Shipped (soft Vendor / PO links; convert-from-PO)</td></tr></tbody></table><h3 id="deferred-2" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-2" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Vendor portal / scorecards</li><li>Expense reimbursement workflows beyond <code>paid</code>; multi-line expenses</li></ul><hr><h2 id="phase-5-—-inventory-shipped" tabindex="-1">Phase 5 — Inventory (shipped) <a class="header-anchor" href="#phase-5-—-inventory-shipped" aria-label="Permalink to &quot;Phase 5 — Inventory (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Products &amp; categories</td><td>Shipped</td></tr><tr><td><a href="/user-guide/warehouses">Warehouses</a> &amp; <a href="/user-guide/inventory">Inventory</a></td><td>Shipped (Inventory requires Products)</td></tr><tr><td>PO receipt → stock-in (soft)</td><td>Shipped</td></tr></tbody></table><h3 id="deferred-3" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-3" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Serial/lot control, valuation, COGS jobs</li></ul><hr><h2 id="phase-6-—-finance-shipped" tabindex="-1">Phase 6 — Finance (shipped) <a class="header-anchor" href="#phase-6-—-finance-shipped" aria-label="Permalink to &quot;Phase 6 — Finance (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/accounting-overview">Accounting</a> (CoA, journals, GL)</td><td>Shipped</td></tr><tr><td><a href="/user-guide/financial-reports">Financial Reports</a> (TB, P&amp;L, BS)</td><td>Shipped (requires Accounting)</td></tr><tr><td>Soft cash movements from Payments / Expenses / transfers</td><td>Shipped</td></tr></tbody></table><h3 id="deferred-4" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-4" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Auto-post from POs / Inventory (AP/COGS)</li><li>Multi-currency accounting / FX; budgets</li></ul><hr><h2 id="phase-7-—-hr-shipped" tabindex="-1">Phase 7 — HR (shipped) <a class="header-anchor" href="#phase-7-—-hr-shipped" aria-label="Permalink to &quot;Phase 7 — HR (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/employees-overview">Employees</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/leave-management-overview">Leave Management</a></td><td>Shipped (requires Employees)</td></tr><tr><td><a href="/user-guide/attendance-overview">Attendance</a></td><td>Shipped (requires Employees; check-in/out timer)</td></tr><tr><td><a href="/user-guide/payroll-overview">Payroll</a></td><td>Shipped (requires Employees; Accounting Mark paid Paid-from + optional draft accrual; own pay slips)</td></tr></tbody></table><h3 id="deferred-5" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-5" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Org chart; employee self-service portal; leave accrual engines; biometric / geofencing; tax engines / bank file export</li></ul><hr><h2 id="phase-8-—-operations-shipped" tabindex="-1">Phase 8 — Operations (shipped) <a class="header-anchor" href="#phase-8-—-operations-shipped" aria-label="Permalink to &quot;Phase 8 — Operations (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/help-desk-overview">Help Desk</a></td><td>Shipped <strong>1.15.0</strong> (customer reply reopens closed/resolved + reply notify; public replies <strong>1.14.0</strong>; TipTap + attachments; portal note authorship <strong>1.13.0</strong>; real-time board sync <strong>1.12.0</strong>; SLA + IMAP; @mentions; status Kanban; soft Communication Templates; shell File a complaint)</td></tr><tr><td><a href="/user-guide/customer-portal-overview">Customer Portal</a></td><td>Shipped <strong>1.3.0</strong> (magic-link + portal 2FA + public KB; Support replies <strong>1.2.0</strong>; projects/tasks <strong>1.1.0</strong>; invite-only Contact accounts; invoices/payments/quotations/contracts; Help Desk submit/track; hard dep Contacts)</td></tr><tr><td><a href="/user-guide/projects-overview">Projects</a></td><td>Shipped <strong>1.8.0</strong> (real-time board sync; workload heatmap <strong>1.6.0</strong>; portfolio Gantt <strong>1.5.0</strong>; milestones <strong>1.4.0</strong>; soft Task <code>project_id</code> + dependencies <strong>tasks 1.5.0</strong>; Automation <code>create_project</code> via <strong>automation 1.4.0</strong>)</td></tr><tr><td><a href="/user-guide/knowledge-base-overview">Knowledge Base</a></td><td>Shipped (internal articles)</td></tr><tr><td><a href="/user-guide/assets-overview">Assets</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/documents-overview">Documents</a></td><td>Shipped (requires Storage)</td></tr><tr><td><a href="/user-guide/analytics-overview">Reports / Analytics</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/announcements-overview">Announcements</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/live-chat-overview">Live Chat</a></td><td>Shipped <strong>1.6.0</strong> (department-routed first-chat FCM; assignee-only follow-up; idle department alert; per-bubble agent name)</td></tr></tbody></table><h3 id="help-desk-deferred" tabindex="-1">Help Desk deferred <a class="header-anchor" href="#help-desk-deferred" aria-label="Permalink to &quot;Help Desk deferred&quot;">​</a></h3><ul><li>Social network DMs (Instagram / Messenger / X / Telegram); auto-create ticket on WhatsApp inbound; bidirectional chat ↔ ticket note sync (WhatsApp escalate + Live Chat escalate + Portal + IMAP already ship — see Help Desk <strong>1.16.0</strong>)</li></ul><h3 id="customer-portal-shipped" tabindex="-1">Customer Portal (shipped) <a class="header-anchor" href="#customer-portal-shipped" aria-label="Permalink to &quot;Customer Portal (shipped)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/customer-portal-overview">Customer Portal</a></td><td>Shipped <strong>1.3.0</strong> (magic-link, portal 2FA, public KB; projects/tasks <strong>1.1.0</strong>; Support <strong>1.2.0</strong>)</td></tr></tbody></table><p>Deferred beyond 1.3.0: online checkout; portal passkeys.</p><h3 id="other-operations-deferred" tabindex="-1">Other Operations deferred <a class="header-anchor" href="#other-operations-deferred" aria-label="Permalink to &quot;Other Operations deferred&quot;">​</a></h3><ul><li>Knowledge Base: anonymous public URLs (portal published read shipped <strong>customer-portal 1.3.0</strong>); nested categories</li><li>Documents: nested folders, versioning, soft record links (on demand)</li><li>Assets: depreciation journals; Product/Inventory FKs; maintenance → Help Desk</li><li>Automation: Marketing campaigns / email campaigns (separate SKUs); branching; standalone <code>send_whatsapp_document</code> action (<code>auto_send_whatsapp</code> on generate_* shipped <strong>1.7.0</strong>; <code>generate_order</code> PO shipped <strong>1.8.0</strong>)</li></ul><hr><h2 id="platform-add-ons-shipped" tabindex="-1">Platform add-ons (shipped) <a class="header-anchor" href="#platform-add-ons-shipped" aria-label="Permalink to &quot;Platform add-ons (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/branded">Branded</a> (white-label)</td><td>Shipped (billable)</td></tr><tr><td><a href="/user-guide/automation-overview">Automation</a></td><td>Shipped (billable; <strong>1.4.0</strong> <code>create_project</code>; <strong>1.5.0</strong> WhatsApp interactive + generate quote/invoice; <strong>1.6.0</strong> email <code>auto_send</code>; <strong>1.7.0</strong> WhatsApp PDF auto-send; <strong>1.8.0</strong> <code>generate_order</code> PO)</td></tr><tr><td><a href="/user-guide/ai-assistant">AI Assistant</a></td><td>Shipped (billable; Lead Copilot + workspace search <strong>1.3.0</strong> + Help Desk triage <strong>1.4.0</strong> + Task triage <strong>1.5.0</strong> + Opportunity triage <strong>1.6.0</strong> + Invoice triage <strong>1.7.0</strong> + Expense triage <strong>1.8.0</strong> + Project triage <strong>1.9.0</strong> + PO triage <strong>1.10.0</strong> + Payment triage <strong>1.11.0</strong> + Lead assign/note <strong>1.12.0</strong> + Estimate triage <strong>1.13.0</strong> + Quotation triage <strong>1.14.0</strong> + Credit Note triage <strong>1.15.0</strong> + Leave triage <strong>1.16.0</strong> + Contract triage <strong>1.17.0</strong> + Contact triage <strong>1.18.0</strong> + Company triage <strong>1.19.0</strong> + product guidance <strong>1.20.0</strong> + Vendor triage <strong>1.21.0</strong> + confirmed writes)</td></tr><tr><td><a href="/user-guide/storage-overview">Storage</a></td><td>Shipped (free packs / quota)</td></tr><tr><td><a href="/developer-guide/tenant-api-webhooks">Tenant API &amp; Webhooks</a></td><td>Shipped (Settings → Developers; payment / Help Desk / credit-note events + endpoint edit)</td></tr><tr><td>Desktop wake push</td><td>Shipped (<strong>FCM only</strong>)</td></tr></tbody></table><hr><h2 id="elosync-mobile" tabindex="-1">EloSync Mobile <a class="header-anchor" href="#elosync-mobile" aria-label="Permalink to &quot;EloSync Mobile&quot;">​</a></h2><p>Native iOS/Android tenant app (Expo SDK 57). Broad module coverage shipped PR-by-PR (CRM, sales, billing, purchasing, HR, Ops, AI, Branded, Storage, etc.). Remaining gaps are module-specific (stats KPIs, trash, some PDF/settings panels remain web-only on mobile v1). See <a href="/user-guide/elosync-mobile">mobile user guide</a>.</p><hr><h2 id="near-term-depth" tabindex="-1">Near-term depth <a class="header-anchor" href="#near-term-depth" aria-label="Permalink to &quot;Near-term depth&quot;">​</a></h2><p>Depth program <strong>0 → 3c</strong> complete (2026-08-31): webhooks event catalog + Developers edit; Credit Notes applied refund (<strong>1.2.0</strong>); Help Desk <code>@mentions</code> <strong>1.5.0</strong>, Kanban <strong>1.6.0</strong>, Communication Template replies <strong>1.7.0</strong>.</p><p>AI workspace search shipped (<strong>ai 1.3.0</strong>): <code>search_workspace</code> fans out across entitled Wave A+B+C modules (CRM/sales/billing/purchasing/ops docs &amp; calendar records).</p><p>Help Desk AI triage shipped (<strong>ai 1.4.0</strong>): <code>get_help_desk_ticket</code> plus confirmed writes for status, assign, and notes (mirrors Help Desk API authz including close/reopen).</p><p>Task AI triage shipped (<strong>ai 1.5.0</strong>): <code>get_task</code> plus confirmed writes for status, assign, and notes (mirrors Task API authz including complete/reopen).</p><p>Opportunity AI triage shipped (<strong>ai 1.6.0</strong>): <code>get_opportunity</code> and <code>get_opportunity_stages</code> plus confirmed writes for stage, assign, and notes (mirrors Opportunity API authz; stage via <code>stage_id</code>).</p><p>Invoice AI triage shipped (<strong>ai 1.7.0</strong>): <code>get_invoice</code> plus confirmed writes for status, assign, and notes (mirrors Invoice HTTP <code>/status</code> authz including send/void gates; overdue list returns assignee id).</p><p>Expense AI triage shipped (<strong>ai 1.8.0</strong>): <code>get_expense</code> plus confirmed writes for status, assign, and notes (mirrors Expense HTTP <code>/status</code> authz including submit/approve/reject/pay/cancel gates; pending-approval list returns assignee id).</p><p>Project AI triage shipped (<strong>ai 1.9.0</strong>): confirmed writes for status, assign, and notes on existing project reads (mirrors Project HTTP <code>/status</code>; get returns assignee id).</p><p>Purchase Order AI triage shipped (<strong>ai 1.10.0</strong>): <code>get_purchase_order</code> plus confirmed writes for status, assign, and notes (mirrors PO HTTP <code>/status</code> authz including send/receive/cancel gates).</p><p>Payment AI triage shipped (<strong>ai 1.11.0</strong>): <code>get_payment</code> plus confirmed writes for status, assign, and notes (Posted→<code>post()</code>, Void→<code>void()</code>; Draft target rejected).</p><p>Lead assign + note shipped (<strong>ai 1.12.0</strong>): confirmed <code>assign_lead</code> / <code>add_lead_note</code> alongside existing Lead reads and status write.</p><p>Estimate AI triage shipped (<strong>ai 1.13.0</strong>): <code>get_estimate</code> plus confirmed writes for status, assign, and notes (mirrors Estimate HTTP <code>/status</code> authz including send/accept gates).</p><p>Quotation AI triage shipped (<strong>ai 1.14.0</strong>): <code>get_quotation</code> plus confirmed writes for status, assign, and notes (mirrors Quotation HTTP <code>/status</code> authz including send/accept gates; title only — no number field; assign uses <code>EligibleOpportunityAssignee</code>).</p><p>Credit Note AI triage shipped (<strong>ai 1.15.0</strong>): <code>get_credit_note</code> plus confirmed writes for status, assign, and notes (Issued→<code>issue()</code>, Applied→<code>apply()</code>, Void→<code>void()</code>, Refunded→<code>refund()</code>; Draft target rejected; assign uses <code>EligibleCreditNoteAssignee</code>).</p><p>Leave AI triage shipped (<strong>ai 1.16.0</strong>): <code>get_leave_request</code> + <code>get_pending_leave_requests</code> plus confirmed <code>approve_leave_request</code> / <code>reject_leave_request</code> (mirrors Leave HTTP approve/reject; no assign/notes; self-approve blocked for non-admin).</p><p>Contract AI triage shipped (<strong>ai 1.17.0</strong>): <code>get_contract</code> plus confirmed writes for status, assign, and notes (Sent→<code>send()</code> with acceptance token; Active from Sent→<code>accept()</code>; other targets→<code>changeStatus</code> with <code>update</code>; assign uses <code>EligibleOpportunityAssignee</code>).</p><p>Contact AI triage shipped (<strong>ai 1.18.0</strong>): <code>get_contact</code> plus confirmed writes for lifecycle status (<code>on_boarded</code>/<code>off_boarded</code>), assign, and notes (<code>EligibleContactAssignee</code>).</p><p>Company AI triage shipped (<strong>ai 1.19.0</strong>): <code>get_company</code> plus confirmed writes for assign and notes (<code>EligibleCompanyAssignee</code>; companies have no lifecycle status).</p><p>Automation <code>create_project</code> shipped (<strong>automation 1.4.0</strong>): creates a Planned project with soft opportunity/company/contact links from the trigger and a note on the related record; template <code>opportunity_stage_create_project</code>.</p><p>Contract PDF + e-signature shipped (<strong>contracts 1.5.0</strong>): branded PDF download, send-for-signature, customer accept links (reuse Quotation accept pattern), staff activate from sent, email with optional PDF + sign link.</p><p><strong>Phased depth Steps 1–4 + convert polish (2026-09-16):</strong> Projects milestones (<strong>projects 1.4.0</strong>) + task dependencies / <code>milestone_id</code> (<strong>tasks 1.5.0</strong>); contract renewal reminders via <code>crm:send-due-notifications</code> + <code>contract_renewal_notice_days</code> (<strong>contracts 1.6.0</strong>); PO per-line partial quantity receive (<strong>purchase-orders 1.5.0</strong>); Calendar Task/Lead overlays (<strong>calendar 1.1.0</strong>); Lead convert polish — <code>LeadConverted</code> / Automation <code>lead.converted</code>, company activity <code>ConvertedFromLead</code>, optional <code>company_id</code>/<code>company_name</code>, <code>conversion_meta</code> names (<strong>leads 1.5.0</strong>).</p><p><strong>Projects portfolio Gantt (2026-09-29):</strong> <code>GET /projects/gantt</code> + SPA Gantt view — catalog <strong>projects 1.5.0</strong>.</p><p><strong>Projects workload heatmap (2026-09-29):</strong> <code>GET /projects/heatmap</code> + SPA Heatmap view — catalog <strong>projects 1.6.0</strong>.</p><p><strong>Workspace record cohesion (2026-09-29):</strong> Contact/Company related hubs (opportunities, help desk, projects, documents); Email CRM links UI (<strong>email 1.4.0</strong>); Documents reverse list filter (<strong>documents 1.6.0</strong>); catalog <strong>contacts 1.6.0</strong> / <strong>companies 1.3.0</strong>. Go-live: <a href="/deployment/workspace-record-cohesion-production-readiness">production readiness</a> (<strong>Go</strong>).</p><p><strong>Contact/Company follow-ups + import/export (2026-09-30):</strong> Follow-ups CRUD + complete on Contacts and Companies (<code>next_follow_up_at</code>, Calendar projection, daily due/overdue reminders via <code>crm:send-due-notifications</code>); CSV/XLSX import wizard (upload → map → options → preview → run, no equal-distribute assignment mode) and CSV/XLSX export. Catalog <strong>contacts 1.6.0 → 1.7.0</strong>, <strong>companies 1.3.0 → 1.4.0</strong>. Closes the &quot;Contact/Company follow-ups / import-export&quot; residual noted in <a href="/deployment/workspace-record-cohesion-production-readiness">workspace record cohesion readiness</a>. Go-live: <a href="/deployment/contacts-companies-follow-ups-import-export-production-readiness">production readiness</a>.</p><p><strong>Leads real-time board sync (2026-09-30):</strong> Private Reverb channel <code>tenant.{id}.leads.board</code> (auth: same tenant + <code>leads.view</code>, mirrors the Live Chat inbox channel) broadcasts <code>LeadCreated</code> / <code>LeadUpdated</code> / <code>LeadStageChanged</code> / <code>LeadAssigned</code> / <code>LeadDeleted</code> from <code>LeadEventSubscriber</code>; SPA <code>useLeadsBoardRealtime</code> hook debounce-invalidates <code>leads/board</code> + <code>leads/stats</code> while the Kanban view is open. Catalog <strong>leads 1.7.0 → 1.8.0</strong>. Closes the &quot;Leads: real-time board sync&quot; deferred item above. Go-live: <a href="/deployment/leads-realtime-board-sync-1-8-0-production-readiness">production readiness</a>.</p><p><strong>Opportunities real-time board sync (2026-10-04):</strong> Private Reverb channel <code>tenant.{id}.opportunities.board</code> (auth: same tenant + <code>opportunities.view</code>, mirrors Leads 1.8.0) broadcasts <code>OpportunityCreated</code> / <code>OpportunityUpdated</code> / <code>OpportunityStageChanged</code> / <code>OpportunityAssigned</code> / <code>OpportunityDeleted</code> from <code>OpportunityEventSubscriber</code>; SPA <code>useOpportunitiesBoardRealtime</code> hook debounce-invalidates <code>opportunities/board</code> + <code>opportunities/stats</code> while the Kanban view is open. Catalog <strong>opportunities 1.2.0 → 1.3.0</strong>. Closes the Opportunities deferred &quot;Real-time board sync&quot; item. Go-live: <a href="/deployment/opportunities-realtime-board-sync-1-3-0-production-readiness">production readiness</a>.</p><p><strong>Tasks real-time board sync (2026-10-04):</strong> Private Reverb channel <code>tenant.{id}.tasks.board</code> (auth: same tenant + <code>tasks.view</code>, mirrors Leads 1.8.0 / Opportunities 1.3.0) broadcasts <code>TaskCreated</code> / <code>TaskUpdated</code> / <code>TaskStatusChanged</code> (with <code>previous_status</code>) / <code>TaskAssigned</code> / <code>TaskDeleted</code> from <code>TaskEventSubscriber</code>; SPA <code>useTasksBoardRealtime</code> hook debounce-invalidates <code>tasks/board</code> + <code>tasks/stats</code> while the Kanban view is open. Catalog <strong>tasks 1.7.0 → 1.8.0</strong>. Closes the Tasks deferred &quot;Real-time board sync&quot; item. Go-live: <a href="/deployment/tasks-realtime-board-sync-1-8-0-production-readiness">production readiness</a>.</p><p><strong>Help Desk real-time board sync (2026-10-05):</strong> Private Reverb channel <code>tenant.{id}.help-desk.board</code> (auth: same tenant + <code>help-desk.view</code>, mirrors Tasks 1.8.0) broadcasts <code>HelpDeskTicketCreated</code> / <code>HelpDeskTicketUpdated</code> / <code>HelpDeskTicketStatusChanged</code> (with <code>previous_status</code>) / <code>HelpDeskTicketAssigned</code> / <code>HelpDeskTicketDeleted</code> from <code>HelpDeskEventSubscriber</code>; SPA <code>useHelpDeskBoardRealtime</code> hook debounce-invalidates <code>help-desk/board</code> + <code>help-desk/stats</code> while the Kanban view is open. Catalog <strong>help-desk 1.11.0 → 1.12.0</strong>. Go-live: <a href="/deployment/help-desk-realtime-board-sync-1-12-0-production-readiness">production readiness</a>.</p><p><strong>Projects real-time board sync (2026-10-05):</strong> Private Reverb channel <code>tenant.{id}.projects.board</code> (auth: same tenant + <code>projects.view</code>, mirrors Help Desk 1.12.0) broadcasts <code>ProjectCreated</code> / <code>ProjectUpdated</code> / <code>ProjectStatusChanged</code> (with <code>previous_status</code>) / <code>ProjectAssigned</code> / <code>ProjectDeleted</code> from <code>ProjectEventSubscriber</code>; SPA <code>useProjectsBoardRealtime</code> hook debounce-invalidates <code>projects/board</code> + <code>projects/stats</code> while the Kanban view is open. Catalog <strong>projects 1.7.0 → 1.8.0</strong>. Go-live: <a href="/deployment/projects-realtime-board-sync-1-8-0-production-readiness">production readiness</a>.</p><p><strong>Automation WhatsApp interactive + document draft actions (2026-10-01):</strong> Actions <code>send_whatsapp_interactive</code> (module <code>whatsapp-cloud</code>, wraps <code>queueInteractive</code>), <code>generate_quotation</code> (module <code>quotations</code>, requires <code>opportunity_id</code>, draft only), and <code>generate_invoice</code> (module <code>invoices</code>, draft only, soft-links from the trigger) via <code>ActionRunner</code>; starter templates <code>opportunity_stage_generate_quotation</code> and <code>whatsapp_inbound_quick_replies</code>. Catalog <strong>automation 1.4.0 → 1.5.0</strong> (no <code>whatsapp-cloud</code> bump). Closes the &quot;Automation interactive send&quot; and &quot;generate quote/invoice&quot; deferred items above (<code>generate_order</code> and auto-send remain deferred). Go-live: <a href="/deployment/automation-whatsapp-interactive-document-actions-1-5-0-production-readiness">production readiness</a>.</p><p><strong>Calendar Google/Outlook sync Phase 1 (2026-09-30):</strong> Per-user OAuth connect (platform-wide Google + Microsoft OAuth apps, env client id/secret) with token storage + refresh + disconnect (<code>calendar_provider_connections</code>). One-way EloSync → provider push (create/update/cancel) for <strong>manual</strong> calendar events only, queued via <code>PushCalendarEventToProviderJob</code> with safe soft-fail (a broken integration never blocks calendar writes). External event ID mapping on <code>calendar_events</code> (<code>external_provider</code> / <code>external_event_id</code>). New permission <code>calendar.manage_integrations</code>. Catalog <strong>calendar 1.3.0 → 1.4.0</strong>. Closes the &quot;Calendar: Google/Outlook sync&quot; deferred item above — two-way sync, named team calendars, and pushing meeting/task/lead overlays remain deferred. Go-live: <a href="/deployment/calendar-google-outlook-sync-1-4-0-production-readiness">production readiness</a>.</p><p><strong>Calendar overlay provider push (2026-10-05):</strong> <code>CalendarEventSourceEnum::shouldPushToProvider()</code> gates <code>PushCalendarEventToProviderJob</code> for <strong>manual + meeting + task + lead</strong> (create/update/cancel/delete). Project/Contact/Company overlays remain deferred. Catalog <strong>calendar 1.4.0 → 1.5.0</strong>. Pest + Playwright one-session overlay sync. Go-live: <a href="/deployment/calendar-overlay-provider-push-1-5-0-production-readiness">production readiness</a>.</p><p><strong>Automation document auto-send (2026-10-05):</strong> Optional <code>auto_send</code> on <code>generate_quotation</code> / <code>generate_invoice</code> — after create, <code>send()</code> then email PDF to bill-to contact/company; fails the run when no recipient email. Catalog <strong>automation 1.5.0 → 1.6.0</strong>. Go-live: <a href="/deployment/automation-document-auto-send-1-6-0-production-readiness">production readiness</a>.</p><p><strong>Automation WhatsApp document auto-send (2026-10-08):</strong> Optional <code>auto_send_whatsapp</code> on <code>generate_quotation</code> / <code>generate_invoice</code> — queues PDF via <code>queueMedia</code> into an open 24h conversation (<code>AutomationDocumentWhatsAppSender</code>). Catalog <strong>automation 1.6.0 → 1.7.0</strong>. Go-live: <a href="/deployment/automation-whatsapp-document-auto-send-1-7-0-production-readiness">production readiness</a>.</p><p><strong>Automation generate_order / Purchase Order (2026-10-08):</strong> Action <code>generate_order</code> creates a Purchase Order draft (<code>purchase-orders</code>); optional email + WhatsApp auto-send; template <code>manual_generate_purchase_order</code>. Catalog <strong>automation 1.7.0 → 1.8.0</strong>. Closes the <code>generate_order</code> + WhatsApp document auto-send deferred leftovers. Go-live: <a href="/deployment/automation-generate-order-1-8-0-production-readiness">production readiness</a>.</p><p><strong>Calendar two-way inbound (2026-10-05):</strong> Provider → EloSync pull as <code>source=external</code> (read-only); Sync now + hourly <code>calendar:pull-provider-events</code>; EloSync-owned mapped events skipped. Catalog <strong>calendar 1.5.0 → 1.6.0</strong>. Go-live: <a href="/deployment/calendar-two-way-inbound-1-6-0-production-readiness">production readiness</a>.</p><p><strong>Calendar Project/Contact/Company overlay provider push (2026-10-08):</strong> <code>CalendarEventSourceEnum::shouldPushToProvider()</code> extended to <strong>Project + Contact + Company</strong> overlays (alongside the existing manual/meeting/task/lead sources), so every sourced calendar event now pushes to connected Google/Outlook accounts the same soft-fail way. Catalog <strong>calendar 1.6.0 → 1.7.0</strong>.</p><p><strong>Calendar webhook-driven inbound sync (2026-10-08):</strong> Google channel + Microsoft Graph subscription watches (<code>createWatch</code>/<code>renewWatch</code>/<code>stopWatch</code>, soft-fail) persisted on <code>calendar_provider_connections.meta</code>; ensured on OAuth connect + Sync now. Public <code>POST /webhooks/calendar-sync/{provider}</code> resolves the connection and queues the existing inbound pull job — near real-time instead of waiting for the hourly backstop. Daily <code>calendar:renew-provider-watches</code> renews before Graph&#39;s ~3-day expiry. Catalog <strong>calendar 1.7.0 → 1.8.0</strong>.</p><p><strong>Help Desk multi-channel intake (2026-10-08):</strong> WhatsApp escalate → ticket (<code>source=whatsapp</code>) peers Live Chat escalate / Portal / IMAP; Help Desk source badges. Catalog <strong>help-desk 1.15.0 → 1.16.0</strong>, <strong>whatsapp-cloud 1.4.0 → 1.5.0</strong>. Closes the “chat beyond IMAP” deferred item (social DMs remain). Go-live: <a href="/deployment/help-desk-1-16-0-production-readiness">production readiness</a>.</p><p><strong>Calendar named team/department calendars (2026-10-08):</strong> New <code>calendars</code> table (name/slug, optional soft-linked <code>department_id</code>, creator); <code>calendar_events.calendar_id</code> nullable FK (<code>null</code> stays personal). <code>GET/POST/PUT/DELETE /calendar/calendars</code> behind new <code>calendar.manage_calendars</code> permission (admin/manager default). Visibility adds creator + department members/manager (only when Departments is entitled) + <code>calendar.view_all</code>; posting to a named calendar needs <code>calendar.create</code> and membership. SPA filter chips (All/Personal/named), manage-calendars dialog, and an event-form calendar picker. Catalog <strong>calendar 1.8.0 → 1.9.0</strong>. Closes the &quot;Calendar: named team calendars&quot; deferred item above.</p><p>Still deferred: named-calendar provider sync/watches; multi-currency; PO/Vendor portals; Automation Marketing/branching. Customer Portal <strong>1.3.0</strong> ships magic-link, portal 2FA, and published KB (online checkout / passkeys remain deferred).</p><p><strong>Customer Portal depth + Help Desk reopen (2026-10-08):</strong> Magic-link + TOTP 2FA + portal published KB; Help Desk closed/resolved reopen on customer reply + dedicated email toggles. Catalog <strong>customer-portal 1.2.0 → 1.3.0</strong>, <strong>help-desk 1.14.0 → 1.15.0</strong>.</p><p>Next when prioritized: demand-driven items below (broader AI tools continue lightly).</p><hr><h2 id="demand-driven-parked" tabindex="-1">Demand-driven / parked <a class="header-anchor" href="#demand-driven-parked" aria-label="Permalink to &quot;Demand-driven / parked&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td>Customer Portal magic-link login</td><td>Beyond <strong>1.1.0</strong> hub — on demand</td></tr><tr><td>Recruitment</td><td>HR expansion — on demand</td></tr><tr><td>Documents nested folders / versioning</td><td>Soft record links shipped (create + reverse list); folders/versioning on demand</td></tr><tr><td>Marketing campaigns / email campaigns</td><td>Separate SKUs; Automation deferred</td></tr><tr><td>Vendor Portal</td><td>Parked</td></tr><tr><td>Multi-currency / multi-branch</td><td>Parked</td></tr><tr><td>Report builder depth</td><td>Parked</td></tr><tr><td>Manufacturing, QA, POS, e-commerce</td><td>Out of active scope unless demanded</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/architecture/module-dependencies">Module dependencies</a></li><li><a href="/changelog/">Changelog</a></li><li><a href="/developer-guide/module-development-guide">Module development guide</a></li><li><a href="/getting-started/platform-freeze">Platform freeze</a></li></ul>',108)])])}const h=t(d,[["render",s]]);export{u as __pageData,h as default};
